from django.contrib.auth.hashers import check_password
from django.db import migrations, models


# Existing PINs are one-way hashes, so they cannot be read back. The two
# defaults branches are provisioned with can be: test for them and store the
# encrypted copy. Everyone else shows "Unknown" until their next PIN reset.
DEFAULT_PINS = ("1234", "0000")


def recover_default_pins(apps, schema_editor):
    from bravepos.pin_vault import seal

    Staff = apps.get_model("bravepos", "Staff")
    for member in Staff.objects.exclude(pin_hash="").filter(pin_encrypted=""):
        for pin in DEFAULT_PINS:
            if check_password(pin, member.pin_hash):
                Staff.objects.filter(pk=member.pk).update(pin_encrypted=seal(pin))
                break


